ALTER TABLE `order_intents` ADD `portfolio_key` text DEFAULT 'default' NOT NULL;--> statement-breakpoint
ALTER TABLE `portfolio_snapshots` ADD `portfolio_key` text DEFAULT 'default' NOT NULL;--> statement-breakpoint
UPDATE order_intents SET portfolio_key = (SELECT 'shadow:' || upper(json_extract(r.config_json, '$.symbol')) || ':' || coalesce(json_extract(r.config_json, '$.strategy.id'), 'agentic-balanced') FROM runs r WHERE r.id = order_intents.run_id) WHERE portfolio_key = 'default' AND EXISTS (SELECT 1 FROM runs r WHERE r.id = order_intents.run_id AND r.mode = 'shadow');--> statement-breakpoint
UPDATE portfolio_snapshots SET portfolio_key = (SELECT 'shadow:' || upper(json_extract(r.config_json, '$.symbol')) || ':' || coalesce(json_extract(r.config_json, '$.strategy.id'), 'agentic-balanced') FROM runs r WHERE r.id = portfolio_snapshots.run_id) WHERE portfolio_key = 'default' AND EXISTS (SELECT 1 FROM runs r WHERE r.id = portfolio_snapshots.run_id AND r.mode = 'shadow');
